 * 'D' a doorway, 'W' a window in the wall, 'o' something already standing on the floor (furniture, a lamp), '.' free
 * floor a player can stand on, ' ' outside. Rows run along +x, successive rows along +z, from the box's corner, so the
 * grid can be copied into layers(g, [x0, y, z0], legend, rows) with characters swapped for furniture.
 */
export function floorPlan(grid, { name, box }) {
  const [x0, y0, z0, x1, y1, z1] = [Math.min(box[0], box[3]), Math.min(box[1], box[4]), Math.min(box[2], box[5]), Math.max(box[0], box[3]), Math.max(box[1], box[4]), Math.max(box[2], box[5])];
  const pass = (x, y, z) => !grid.inBounds(x, y, z) || PASS.test(strip(grid.blockAt(x, y, z)));
